module.exports = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Package Whisperer — Thoughtful Ring Caretaking</title>\n  <link rel=\"stylesheet\" href=\"/css/styles.css\">\n  <link rel=\"stylesheet\" href=\"/css/motion.css\">\n  <link rel=\"icon\" href=\"data:image/svg+xml,<svg xmlns=%22http://www.w3.org/2000/svg%22 viewBox=%220 0 100 100%22><text y=%22.9em%22 font-size=%2290%22>📦</text></svg>\">\n</head>\n<body>\n  <!-- Atmospheric Ambient Background Light -->\n  <div class=\"ambient-glow\">\n    <div class=\"ambient-orb orb-top-left\"></div>\n    <div class=\"ambient-orb orb-top-right\"></div>\n  </div>\n\n  <div class=\"app-container\">\n    <!-- Top Navigation Bar -->\n    <header class=\"top-bar\">\n      <div class=\"brand\" onclick=\"switchTab('landing')\" style=\"cursor: pointer;\">\n        <div class=\"brand-icon\">📦</div>\n        <div>\n          <h1 class=\"brand-title kinetic-gradient-text\">Package Whisperer</h1>\n        </div>\n        <span class=\"brand-tag\">Ring + Bedrock</span>\n      </div>\n\n      <nav class=\"nav-tabs\">\n        <button class=\"tab-btn active\" data-tab=\"landing\">\n          <span>✨</span> <span>Overview</span>\n        </button>\n        <button class=\"tab-btn\" data-tab=\"caretaker\">\n          <span>🛡️</span> <span>Caretaker Hub</span>\n        </button>\n        <button class=\"tab-btn\" data-tab=\"resident\">\n          <span>🏡</span> <span>Resident View</span>\n        </button>\n        <button class=\"tab-btn\" data-tab=\"simulator\">\n          <span>⚡</span> <span>Simulator &amp; Lab</span>\n        </button>\n        <button class=\"tab-btn\" data-tab=\"architecture\">\n          <span>📐</span> <span>How It Works</span>\n        </button>\n      </nav>\n\n      <div class=\"top-actions\">\n        <div class=\"motion-mode-pill\" id=\"motionModeBtn\" onclick=\"MotionDesign.toggleMode()\" title=\"Toggle Animation &amp; Kinetic Type Mode\">\n          <span>✨</span> <span>Motion: Lively</span>\n        </div>\n        <div class=\"pill-badge\" id=\"quietHoursPill\">\n          <span class=\"status-dot pulse\"></span> <span>Caretaker active</span>\n        </div>\n        <div style=\"display: flex; align-items: center; gap: 4px;\">\n          <button class=\"btn-icon\" id=\"soundToggleBtn\" title=\"Ambient Sound\">🔊</button>\n          <div class=\"audio-equalizer-wrap\" id=\"audioEqualizer\" title=\"Soundwave Visualizer\">\n            <div class=\"eq-bar bar-1\"></div>\n            <div class=\"eq-bar bar-2\"></div>\n            <div class=\"eq-bar bar-3\"></div>\n            <div class=\"eq-bar bar-4\"></div>\n          </div>\n        </div>\n      </div>\n    </header>\n\n    <!-- TAB 0: LANDING PAGE (/ route — Visually striking, colorful & animated) -->\n    <main id=\"tab-landing\" class=\"tab-view\">\n      <!-- Animated Gradient Hero Section -->\n      <section class=\"landing-hero-section\">\n        <!-- Floating Ambient Gradient Orbs (Amber #C98A2C, Sage #5B7A5E, Sky Blue #3F6C86) -->\n        <div class=\"landing-orbs-container\" aria-hidden=\"true\">\n          <div class=\"landing-orb orb-amber\"></div>\n          <div class=\"landing-orb orb-sage\"></div>\n          <div class=\"landing-orb orb-sky\"></div>\n        </div>\n\n        <div class=\"landing-hero-content\">\n          <!-- Colorful Pill Badge -->\n          <div class=\"landing-pill-badge\">\n            <span class=\"landing-pill-dot\"></span>\n            <span class=\"landing-pill-text\">Ring IoT + AWS Bedrock Hackathon</span>\n            <span class=\"landing-pill-tag\">Calm Technology</span>\n          </div>\n\n          <!-- Staggered Animated Headline -->\n          <h1 class=\"landing-headline\" aria-label=\"Some things don't need an alarm\">\n            <span class=\"landing-word\" style=\"--w-i: 1\">Some</span>\n            <span class=\"landing-word\" style=\"--w-i: 2\">things</span>\n            <span class=\"landing-word highlight-sage\" style=\"--w-i: 3\">don't</span>\n            <span class=\"landing-word highlight-sage\" style=\"--w-i: 4\">need</span>\n            <span class=\"landing-word\" style=\"--w-i: 5\">an</span>\n            <span class=\"landing-word highlight-amber underline-drift\" style=\"--w-i: 6\">alarm.</span>\n          </h1>\n\n          <!-- Subtitle with colorful accents from existing palette -->\n          <p class=\"landing-subhead\">\n            Traditional smart cameras trigger <span class=\"accent-brick\">alarm fatigue</span> with constant rings and motion pings. \n            <strong>Package Whisperer</strong> gives residents an unhurried <span class=\"accent-sage\">peaceful retrieval window</span>, \n            only escalating with <span class=\"accent-sky\">Amazon Bedrock AI digests</span> when check-in assistance is genuinely helpful.\n          </p>\n\n          <!-- Primary Interactive Action Cards (Resident View vs Caretaker View with lively hover states) -->\n          <div class=\"landing-action-cards\">\n            <!-- Card 1: See Resident View -->\n            <div class=\"landing-card card-resident\" onclick=\"switchTab('resident')\" role=\"button\" tabindex=\"0\">\n              <div class=\"card-glow-halo\"></div>\n              <div class=\"card-badge badge-sage\">\n                <span>🏡</span> <span>For In-Home Resident</span>\n              </div>\n              <div class=\"card-icon-wrap icon-sage\">\n                <span class=\"card-main-icon\">🌿</span>\n              </div>\n              <h3 class=\"card-title\">See Resident View</h3>\n              <p class=\"card-desc\">\n                Tranquil, zero-stress porch display. An ambient chime and tactile \"Got it!\" button preserve autonomy with zero fear-inducing alerts.\n              </p>\n              <div class=\"card-features\">\n                <span class=\"feature-tag\">🍃 Zero Alarm Fatigue</span>\n                <span class=\"feature-tag\">✋ One-Touch Resolution</span>\n              </div>\n              <div class=\"card-cta cta-sage\">\n                <span>Explore Resident View</span>\n                <span class=\"cta-arrow\">→</span>\n              </div>\n            </div>\n\n            <!-- Card 2: See Caretaker View -->\n            <div class=\"landing-card card-caretaker\" onclick=\"switchTab('caretaker')\" role=\"button\" tabindex=\"0\">\n              <div class=\"card-glow-halo\"></div>\n              <div class=\"card-badge badge-sky\">\n                <span>🛡️</span> <span>For Remote Caregivers</span>\n              </div>\n              <div class=\"card-icon-wrap icon-sky\">\n                <span class=\"card-main-icon\">📨</span>\n              </div>\n              <h3 class=\"card-title\">See Caretaker Hub</h3>\n              <p class=\"card-desc\">\n                Live delivery timeline, 10 PM–7 AM quiet hours guard, and Bedrock Claude Haiku 4.5 digests tailored to caregiver tone preferences.\n              </p>\n              <div class=\"card-features\">\n                <span class=\"feature-tag\">🌙 Quiet Hours Guard</span>\n                <span class=\"feature-tag\">🤖 Bedrock Tone Synthesis</span>\n              </div>\n              <div class=\"card-cta cta-sky\">\n                <span>Explore Caretaker Hub</span>\n                <span class=\"cta-arrow\">→</span>\n              </div>\n            </div>\n\n            <!-- Card 3: Interactive Event Simulator -->\n            <div class=\"landing-card card-simulator\" onclick=\"switchTab('simulator')\" role=\"button\" tabindex=\"0\">\n              <div class=\"card-glow-halo\"></div>\n              <div class=\"card-badge badge-amber\">\n                <span>⚡</span> <span>Interactive Demo Lab</span>\n              </div>\n              <div class=\"card-icon-wrap icon-amber\">\n                <span class=\"card-main-icon\">🔬</span>\n              </div>\n              <h3 class=\"card-title\">Test Event Simulator</h3>\n              <p class=\"card-desc\">\n                Simulate Ring doorbell rings, courier drop-offs, resident collections, and test live Amazon Bedrock tone escalation synthesis.\n              </p>\n              <div class=\"card-features\">\n                <span class=\"feature-tag\">🔔 Doorbell &amp; Motion</span>\n                <span class=\"feature-tag\">🧠 Live AI Generator</span>\n              </div>\n              <div class=\"card-cta cta-amber\">\n                <span>Launch Simulator Lab</span>\n                <span class=\"cta-arrow\">→</span>\n              </div>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- Section: The Three \"How It Works\" Numbered Steps (Animates on Scroll with Drawing Line) -->\n      <section class=\"landing-steps-section\" id=\"landingStepsSection\">\n        <div class=\"steps-header\">\n          <span class=\"steps-eyebrow\">Architecture &amp; Flow</span>\n          <h2 class=\"steps-heading\">How Package Whisperer Works</h2>\n          <p class=\"steps-sub\">Three thoughtful stages designed to protect resident dignity and prevent caregiver burnout.</p>\n        </div>\n\n        <div class=\"landing-steps-track\">\n          <!-- The Colored Connecting Line that draws itself between the steps -->\n          <div class=\"steps-draw-line\" id=\"stepsDrawLine\" aria-hidden=\"true\"></div>\n\n          <!-- Step 1: Doorstep Drop-off (Amber #C98A2C) -->\n          <div class=\"landing-step-card step-amber\" data-step=\"1\">\n            <div class=\"step-num-bubble\">01</div>\n            <div class=\"step-icon-box\">📦</div>\n            <h3 class=\"step-card-title\">Doorstep Drop-off</h3>\n            <p class=\"step-card-text\">\n              Ring camera or doorbell detects a package arrival. The system verifies the HMAC signature and logs the delivery <span class=\"highlight-amber\">silently</span>.\n            </p>\n            <div class=\"step-tag-pill\">Ring Webhook + Classifier</div>\n          </div>\n\n          <!-- Step 2: Peaceful Window (Sage #5B7A5E) -->\n          <div class=\"landing-step-card step-sage\" data-step=\"2\">\n            <div class=\"step-num-bubble\">02</div>\n            <div class=\"step-icon-box\">⏳</div>\n            <h3 class=\"step-card-title\">Peaceful Retrieval Window</h3>\n            <p class=\"step-card-text\">\n              The resident gets an unhurried window (4 hours default, or 30s in demo) to collect packages. Resident pickup <span class=\"highlight-sage\">self-resolves</span> with zero alarms sent.\n            </p>\n            <div class=\"step-tag-pill\">Autonomy Preserved</div>\n          </div>\n\n          <!-- Step 3: Thoughtful AI Escalation (Sky Blue #3F6C86) -->\n          <div class=\"landing-step-card step-sky\" data-step=\"3\">\n            <div class=\"step-num-bubble\">03</div>\n            <div class=\"step-icon-box\">🤖</div>\n            <h3 class=\"step-card-title\">Thoughtful AI Escalation</h3>\n            <p class=\"step-card-text\">\n              Only if uncollected past the window does <span class=\"highlight-sky\">Amazon Bedrock</span> generate an empathetic, tone-tuned notification for the caregiver, respecting quiet hours.\n            </p>\n            <div class=\"step-tag-pill\">Claude Haiku 4.5 AI</div>\n          </div>\n        </div>\n      </section>\n\n      <!-- Bottom Callout Band: Quick Mode Switch & Hackathon Tech Stack -->\n      <section class=\"landing-stack-banner\">\n        <div class=\"stack-banner-left\">\n          <div class=\"stack-badge\">Built For Hackathon</div>\n          <div class=\"stack-title\">Ring Developer Track + Amazon Bedrock Runtime</div>\n          <div class=\"stack-chips\">\n            <span class=\"chip\">Ring Webhook HMAC-SHA256</span>\n            <span class=\"chip\">Amazon Bedrock (Claude Haiku 4.5)</span>\n            <span class=\"chip\">SigV4 Request Dispatch</span>\n            <span class=\"chip\">DFD Level 1 &amp; Level 2 Spec</span>\n            <span class=\"chip\">Zero Alarm Fatigue</span>\n          </div>\n        </div>\n        <div class=\"stack-banner-actions\">\n          <button class=\"btn-primary\" onclick=\"switchTab('caretaker')\">\n            Open Caretaker Hub →\n          </button>\n          <button class=\"btn-secondary\" onclick=\"switchTab('resident')\">\n            Open Resident Screen\n          </button>\n        </div>\n      </section>\n    </main>\n\n    <!-- TAB 1: CARETAKER HUB -->\n    <main id=\"tab-caretaker\" class=\"tab-view\" style=\"display: none;\">\n      <!-- Living Vector Porch Motion Stage -->\n      <section class=\"porch-stage-card\" id=\"porchMotionStage\">\n        <div class=\"porch-stage-header\">\n          <div class=\"porch-stage-title-wrap\">\n            <span style=\"font-size: 20px;\">🏡</span>\n            <div>\n              <div style=\"font-family: var(--font-serif); font-size: 16px; font-weight: 600; color: var(--ink);\">\n                Living Porch Motion Stage\n              </div>\n              <div style=\"font-size: 11.5px; color: var(--ink-faint);\">\n                Live vector diorama reflecting front door deliveries &amp; peaceful retrievals\n              </div>\n            </div>\n            <span class=\"porch-stage-badge\" id=\"porchSkyBadge\">☀️ Daytime Vigil</span>\n          </div>\n\n          <div class=\"porch-stage-controls\">\n            <button class=\"porch-tool-btn primary\" onclick=\"MotionDesign.PorchStage.playFullStory()\" title=\"Play full delivery to pickup story animation\">\n              <span>🎬</span> <span>Play Story</span>\n            </button>\n            <button class=\"porch-tool-btn\" onclick=\"MotionDesign.PorchStage.dropPackage()\" title=\"Simulate dropping parcel\">\n              <span>📦</span> <span>Drop Box</span>\n            </button>\n            <button class=\"porch-tool-btn\" onclick=\"MotionDesign.PorchStage.ringDoorbell()\" title=\"Ring doorbell with sonar waves\">\n              <span>🔔</span> <span>Ring Bell</span>\n            </button>\n            <button class=\"porch-tool-btn\" onclick=\"MotionDesign.PorchStage.residentPickup()\" title=\"Resident steps out and picks up package\">\n              <span>🚶</span> <span>Resident Pick Up</span>\n            </button>\n            <button class=\"porch-tool-btn\" onclick=\"MotionDesign.PorchStage.toggleSky()\" title=\"Toggle Day and Night Sky\">\n              <span>🌙</span> <span>Day / Night</span>\n            </button>\n          </div>\n        </div>\n\n        <!-- Animated Stage Viewport -->\n        <div class=\"porch-viewport\" id=\"porchViewport\">\n          <!-- Sky Elements -->\n          <div class=\"sky-layer\">\n            <div class=\"celestial-sun\"></div>\n            <div class=\"celestial-moon\"></div>\n            <div class=\"star-cluster\" id=\"porchStarCluster\"></div>\n            <div class=\"cloud cloud-1\"></div>\n            <div class=\"cloud cloud-2\"></div>\n          </div>\n\n          <!-- House Architecture Structure -->\n          <div class=\"porch-house-structure\">\n            <div class=\"porch-roof\"></div>\n            <div class=\"porch-wall\"></div>\n\n            <!-- Warm Porch Lantern -->\n            <div class=\"porch-lantern-wrap\">\n              <div class=\"lantern-bracket\"></div>\n              <div class=\"lantern-housing\">\n                <div class=\"lantern-glass\">\n                  <div class=\"lantern-filament\"></div>\n                </div>\n              </div>\n              <div class=\"lantern-glow-cone\"></div>\n            </div>\n\n            <!-- Front Wooden Door -->\n            <div class=\"interior-glow-backdrop\"></div>\n            <div class=\"porch-door-frame\">\n              <div class=\"porch-door\" id=\"porchFrontDoor\">\n                <div class=\"door-window\"></div>\n                <div class=\"door-panel\"></div>\n                <div class=\"door-panel\"></div>\n                <div class=\"door-handle\"></div>\n              </div>\n            </div>\n\n            <!-- Ring Video Doorbell Device -->\n            <div class=\"ring-doorbell-device\" onclick=\"MotionDesign.PorchStage.ringDoorbell()\" title=\"Click to ring Ring doorbell\">\n              <div class=\"ring-lens\"></div>\n              <div class=\"ring-button\" id=\"ringDoorbellBtn\">\n                <div class=\"sonar-wave-container\">\n                  <div class=\"sonar-ring ring-1\" id=\"sonarRing1\"></div>\n                  <div class=\"sonar-ring ring-2\" id=\"sonarRing2\"></div>\n                  <div class=\"sonar-ring ring-3\" id=\"sonarRing3\"></div>\n                </div>\n              </div>\n            </div>\n\n            <!-- Welcome Doormat -->\n            <div class=\"porch-mat\">Welcome</div>\n\n            <!-- Animated Parcel on Doorstep -->\n            <div class=\"animated-parcel\" id=\"animatedPorchParcel\" onclick=\"MotionDesign.PorchStage.residentPickup()\" title=\"Click to pick up package!\">\n              <div class=\"parcel-beacon\">⏳ Waiting</div>\n              <div class=\"parcel-box\">\n                <div class=\"parcel-tape\"></div>\n                <div class=\"parcel-label\"></div>\n              </div>\n            </div>\n\n            <!-- Animated Resident Character -->\n            <div class=\"resident-person\" id=\"porchResident\">\n              <div class=\"character-head\"></div>\n              <div class=\"character-torso\"></div>\n              <div class=\"character-legs\">\n                <div class=\"character-leg\"></div>\n                <div class=\"character-leg\"></div>\n              </div>\n            </div>\n          </div>\n\n          <!-- Ground Baseline -->\n          <div class=\"porch-ground\"></div>\n\n          <!-- Animated Delivery Van & Courier -->\n          <div class=\"delivery-van\" id=\"porchDeliveryVan\">\n            <div class=\"van-headlight\"></div>\n            <div class=\"van-cabin-window\"></div>\n            <div class=\"van-body\">RING</div>\n            <div class=\"van-wheel back\"></div>\n            <div class=\"van-wheel front\"></div>\n          </div>\n\n          <div class=\"courier-person\" id=\"porchCourier\">\n            <div class=\"character-head\">\n              <div class=\"character-cap\"></div>\n            </div>\n            <div class=\"character-torso\"></div>\n            <div class=\"character-legs\">\n              <div class=\"character-leg\"></div>\n              <div class=\"character-leg\"></div>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <!-- Active Delivery Hero Card (Animated SVG countdown ring) -->\n      <section class=\"active-deliveries-section\" id=\"activeDeliveriesSection\"></section>\n\n      <!-- Key Metrics Row -->\n      <section class=\"stats-grid\">\n        <div class=\"stat-card\">\n          <div class=\"stat-header\">\n            <span class=\"stat-title\">Deliveries Watched</span>\n            <span class=\"stat-icon\">📦</span>\n          </div>\n          <div class=\"stat-value\" id=\"statTotal\">0</div>\n          <div class=\"stat-sub\">Total Ring delivery events</div>\n        </div>\n\n        <div class=\"stat-card sage\">\n          <div class=\"stat-header\">\n            <span class=\"stat-title\">Self-Resolved</span>\n            <span class=\"stat-icon\">🌱</span>\n          </div>\n          <div class=\"stat-value\" id=\"statResolvedRate\">100%</div>\n          <div class=\"stat-sub\">Collected without caregiver alert</div>\n        </div>\n\n        <div class=\"stat-card brick\">\n          <div class=\"stat-header\">\n            <span class=\"stat-title\">Caregiver Escalations</span>\n            <span class=\"stat-icon\">📨</span>\n          </div>\n          <div class=\"stat-value\" id=\"statEscalated\">0</div>\n          <div class=\"stat-sub\">AI digests sent after window</div>\n        </div>\n\n        <div class=\"stat-card amber\">\n          <div class=\"stat-header\">\n            <span class=\"stat-title\">Active Windows</span>\n            <span class=\"stat-icon\">⏳</span>\n          </div>\n          <div class=\"stat-value\" id=\"statPending\">0</div>\n          <div class=\"stat-sub\">Parcels currently outside</div>\n        </div>\n      </section>\n\n      <!-- Sensitivity & Caregiver Settings Controls -->\n      <section class=\"controls-bar\">\n        <div class=\"controls-group\">\n          <span class=\"control-label\">AI Caregiver Tone:</span>\n          <select id=\"toneSelect\" class=\"select-custom\" onchange=\"updateToneSetting()\">\n            <option value=\"gentle\">Warm &amp; Reassuring (Gentle family nudge)</option>\n            <option value=\"direct\">Direct &amp; Concise (Clean status alert)</option>\n            <option value=\"urgent\">Urgent / Wellbeing (Safety check-in)</option>\n          </select>\n        </div>\n\n        <div class=\"divider-vertical\"></div>\n\n        <div class=\"controls-group\">\n          <span class=\"control-label\">Retrieval Window:</span>\n          <select id=\"windowSelect\" class=\"select-custom\" onchange=\"updateRetrievalWindowSetting()\">\n            <option value=\"0.5\">30 Seconds (Hackathon Live Demo)</option>\n            <option value=\"1\">1 Minute (Quick Testing)</option>\n            <option value=\"15\">15 Minutes (Short Porch Window)</option>\n            <option value=\"60\">1 Hour (Standard Day Window)</option>\n            <option value=\"240\" selected>4 Hours (Production Default)</option>\n          </select>\n        </div>\n\n        <div class=\"divider-vertical\"></div>\n\n        <div class=\"controls-group\">\n          <label class=\"switch-label\">\n            <input type=\"checkbox\" id=\"qhCheckbox\" onchange=\"updateQuietHoursSetting()\" checked>\n            <span>Quiet Hours (10 PM – 7 AM)</span>\n          </label>\n        </div>\n      </section>\n\n      <!-- Main Dashboard Grid -->\n      <div class=\"dashboard-grid\">\n        <!-- Live Activity Timeline -->\n        <div class=\"content-card\">\n          <div class=\"card-header\">\n            <h2 class=\"card-title\">Live Activity Timeline</h2>\n            <div class=\"filter-pills\">\n              <button class=\"filter-btn active\" data-filter=\"all\">All</button>\n              <button class=\"filter-btn\" data-filter=\"retrieved\">Retrieved</button>\n              <button class=\"filter-btn\" data-filter=\"pending\">Waiting</button>\n              <button class=\"filter-btn\" data-filter=\"escalated\">Escalated</button>\n              <button class=\"filter-btn\" data-filter=\"held\">Quiet</button>\n            </div>\n          </div>\n          <div class=\"events-list\" id=\"eventsList\">\n            <!-- Dynamic items rendered by app.js -->\n          </div>\n        </div>\n\n        <!-- Sidebar: Monitored Porch Cameras & Philosophy -->\n        <aside class=\"sidebar-col\">\n          <div class=\"content-card\">\n            <div class=\"card-header\">\n              <h2 class=\"card-title\">Connected Doors</h2>\n              <span class=\"brand-tag\">3 Online</span>\n            </div>\n            <div style=\"padding: 16px 20px;\" id=\"deviceList\">\n              <!-- Rendered by app.js with live status -->\n            </div>\n          </div>\n\n          <div class=\"content-card\" style=\"padding: 24px 26px; background: linear-gradient(135deg, #FFFFFF 0%, #FAF8F4 100%);\">\n            <h3 style=\"font-family: var(--font-serif); font-size: 17px; margin-bottom: 8px; color: var(--ink);\">Quiet Care Philosophy</h3>\n            <p style=\"font-size: 13.5px; color: var(--ink-soft); line-height: 1.6; margin-bottom: 16px;\">\n              Smart cameras flood families with false alarms for every passing delivery truck or animal. Package Whisperer protects the resident's autonomy first, keeping life quiet and calm until a check-in is genuinely helpful.\n            </p>\n            <button class=\"btn-secondary\" style=\"font-size: 12.5px; width: 100%;\" onclick=\"switchTab('simulator')\">\n              ⚡ Open Event Simulator\n            </button>\n          </div>\n        </aside>\n      </div>\n    </main>\n\n    <!-- TAB 2: RESIDENT CALM VIEW (Ambient Wall / Tablet Screen) -->\n    <main id=\"tab-resident\" class=\"tab-view\" style=\"display: none;\">\n      <div class=\"resident-screen-wrap\" id=\"residentContainer\">\n        <!-- Rendered dynamically by app.js -->\n      </div>\n    </main>\n\n    <!-- TAB 3: SIMULATOR & LAB -->\n    <main id=\"tab-simulator\" class=\"tab-view\" style=\"display: none;\">\n      <div class=\"sim-grid\">\n        <!-- Event Simulator Column -->\n        <div class=\"sim-box\">\n          <h2 class=\"sim-box-title\"><span>⚡</span> Ring Event Simulator</h2>\n          <p class=\"sim-box-desc\">\n            Simulate Ring doorbell and camera webhook events to inspect the event classifier and escalation state machine in real time.\n          </p>\n\n          <div style=\"margin-bottom: 18px;\">\n            <label class=\"control-label\" style=\"display: block; margin-bottom: 6px;\">Target Door / Porch:</label>\n            <select id=\"simDeviceSelect\" class=\"select-custom\" style=\"width: 100%;\">\n              <option value=\"cam1\">Front door (cam1) — Main Porch</option>\n              <option value=\"cam2\">Back door (cam2) — Garden Patio</option>\n              <option value=\"cam3\">Garage porch (cam3) — Side Driveway</option>\n            </select>\n          </div>\n\n          <div class=\"sim-buttons-grid\">\n            <div class=\"sim-btn-row\" onclick=\"triggerSimulatorEvent('button_press')\">\n              <div class=\"sim-btn-left\">\n                <span class=\"sim-btn-icon\">🔔</span>\n                <div>\n                  <div class=\"sim-btn-title\">Simulate Doorbell Ring</div>\n                  <div class=\"sim-btn-sub\">Classified as Delivery (High confidence) &bull; Starts quiet window</div>\n                </div>\n              </div>\n              <button class=\"sim-btn-trigger\">Trigger</button>\n            </div>\n\n            <div class=\"sim-btn-row\" onclick=\"triggerSimulatorEvent('courier_dropoff')\">\n              <div class=\"sim-btn-left\">\n                <span class=\"sim-btn-icon\">📦</span>\n                <div>\n                  <div class=\"sim-btn-title\">Simulate Courier Drop-off</div>\n                  <div class=\"sim-btn-sub\">Human motion with 20s visit &bull; Classified as delivery visit pattern</div>\n                </div>\n              </div>\n              <button class=\"sim-btn-trigger\">Trigger</button>\n            </div>\n\n            <div class=\"sim-btn-row\" onclick=\"triggerSimulatorEvent('resident_retrieval')\">\n              <div class=\"sim-btn-left\">\n                <span class=\"sim-btn-icon\">🚶</span>\n                <div>\n                  <div class=\"sim-btn-title\">Simulate Resident Pickup</div>\n                  <div class=\"sim-btn-sub\">Short human motion after delivery &bull; Self-resolves peacefully without alert</div>\n                </div>\n              </div>\n              <button class=\"sim-btn-trigger\">Trigger</button>\n            </div>\n\n            <div class=\"sim-btn-row\" onclick=\"triggerSimulatorEvent('animal_motion')\">\n              <div class=\"sim-btn-left\">\n                <span class=\"sim-btn-icon\">🐾</span>\n                <div>\n                  <div class=\"sim-btn-title\">Simulate Animal Motion</div>\n                  <div class=\"sim-btn-sub\">Pet or wildlife passing by &bull; Filtered out, zero false alerts</div>\n                </div>\n              </div>\n              <button class=\"sim-btn-trigger\">Trigger</button>\n            </div>\n\n            <div class=\"sim-btn-row\" onclick=\"triggerSimulatorEvent('passerby_motion')\">\n              <div class=\"sim-btn-left\">\n                <span class=\"sim-btn-icon\">🏃</span>\n                <div>\n                  <div class=\"sim-btn-title\">Simulate Passerby (Long Motion)</div>\n                  <div class=\"sim-btn-sub\">Motion lasting &gt;60s on sidewalk &bull; Filtered out as non-delivery</div>\n                </div>\n              </div>\n              <button class=\"sim-btn-trigger\">Trigger</button>\n            </div>\n          </div>\n        </div>\n\n        <!-- AI Digest Inspector Column -->\n        <div class=\"sim-box\">\n          <h2 class=\"sim-box-title\"><span>🤖</span> Amazon Bedrock AI Generator</h2>\n          <p class=\"sim-box-desc\">\n            Test prompt synthesis and generation with Amazon Bedrock (Claude Haiku 4.5) and resilient fallback execution.\n          </p>\n\n          <div style=\"display: flex; gap: 10px; margin-bottom: 18px;\">\n            <button class=\"btn-amber\" id=\"btnGenerateDigest\" style=\"flex: 1; padding: 13px;\" onclick=\"runBedrockTest()\">\n              <span>✨</span> <span>Generate Live AI Digest</span>\n            </button>\n            <button class=\"btn-secondary\" onclick=\"resetDemoData()\" title=\"Reset to sample demo data\">\n              <span>🧹</span> <span>Reset Data</span>\n            </button>\n          </div>\n\n          <!-- Formatted Digest Card Preview (Shows complete writing prominently) -->\n          <div class=\"digest-card-preview\" id=\"digestCardPreview\" style=\"display: none;\">\n            <div class=\"digest-preview-header\">\n              <span class=\"digest-badge\" id=\"previewBadge\">💌 Generated Caretaker Digest</span>\n              <span class=\"digest-source-pill\" id=\"previewSource\">AWS Bedrock</span>\n            </div>\n            <p class=\"digest-preview-text\" id=\"previewDigestText\"></p>\n            <div class=\"digest-preview-meta\" id=\"previewMeta\"></div>\n          </div>\n\n          <div style=\"display: flex; justify-content: space-between; align-items: center; margin-bottom: 6px;\">\n            <span class=\"control-label\">Live Payload &amp; Response Inspector:</span>\n            <div style=\"display: flex; gap: 8px; align-items: center;\">\n              <button class=\"btn-secondary\" style=\"font-size: 11px; padding: 3px 8px;\" onclick=\"copyInspectorOutput()\" title=\"Copy entire writing to clipboard\">\n                📋 Copy\n              </button>\n              <span style=\"font-size: 11px; color: var(--ink-faint);\">Model: Claude Haiku 4.5</span>\n            </div>\n          </div>\n\n          <pre class=\"prompt-inspector\" id=\"aiInspectorOutput\">Ready to test. Click \"Generate Live AI Digest\" to invoke Amazon Bedrock...</pre>\n\n          <div style=\"margin-top: 20px; padding: 16px 20px; background: var(--surface-muted); border-radius: var(--radius-md); font-size: 13px; line-height: 1.6; border: 1px solid var(--border);\">\n            <div style=\"margin-bottom: 4px;\"><strong>AWS Bedrock Model:</strong> <span style=\"font-family: var(--font-mono); font-size: 11.5px;\">us.anthropic.claude-haiku-4-5-20251001-v1:0</span></div>\n            <div><strong>Fail-safe Mechanism:</strong> Automatic tone-matched natural language fallback when daily token quota is reached (HTTP 429 Protection).</div>\n          </div>\n        </div>\n      </div>\n    </main>\n\n    <!-- TAB 4: REDUCED & ANIMATED PIPELINE JOURNEY (Simple vs Tech Mode) -->\n    <main id=\"tab-architecture\" class=\"tab-view\" style=\"display: none;\">\n      <div class=\"content-card pipeline-container\">\n        <!-- Header Row with Mode Toggle -->\n        <div class=\"pipeline-header-row\">\n          <div>\n            <h2 class=\"pipeline-title\">How Package Whisperer Works</h2>\n            <p class=\"pipeline-subtitle\">From Ring doorstep motion to calm caregiver check-ins.</p>\n          </div>\n\n          <!-- Mode Switcher Pill -->\n          <div class=\"pipeline-mode-toggle\">\n            <button class=\"mode-btn active\" id=\"btnModeSimple\" onclick=\"setPipelineMode('simple')\">\n              <span>🌿</span> <span>Simple Story</span>\n            </button>\n            <button class=\"mode-btn\" id=\"btnModeTech\" onclick=\"setPipelineMode('tech')\">\n              <span>⚙️</span> <span>Technical Spec</span>\n            </button>\n          </div>\n        </div>\n\n        <!-- Animated Control Bar -->\n        <div class=\"pipeline-anim-bar\">\n          <button class=\"anim-play-btn\" id=\"btnPlayJourney\" onclick=\"playPipelineJourney()\">\n            <span id=\"playIcon\">▶</span> <span id=\"playText\">Play Animated Flow</span>\n          </button>\n          <div class=\"anim-status-indicator\">\n            <div class=\"anim-pulse-box\"></div>\n            <span id=\"animStatusText\">Click \"Play Animated Flow\" or tap any step to inspect</span>\n          </div>\n        </div>\n\n        <!-- 4-Step Interactive Animated Journey Track -->\n        <div class=\"pipeline-journey-track\">\n          <div class=\"pipeline-active-line\" id=\"pipelineProgressLine\">\n            <div class=\"pipeline-traveler-icon\" id=\"pipelineTraveler\">📦</div>\n          </div>\n\n          <!-- Step 1: Drop-off -->\n          <div class=\"pipe-step-card active-step\" id=\"pipeStep1\" onclick=\"focusPipelineStep(1)\">\n            <div class=\"pipe-step-icon-halo\">📦</div>\n            <span class=\"pipe-step-num\">Step 1</span>\n            <h3 class=\"pipe-step-title\">Doorstep Drop-off</h3>\n            <p class=\"pipe-step-desc\">A courier leaves a parcel or rings the bell. The system acknowledges the arrival silently without blaring alarms.</p>\n            <div class=\"pipe-tech-detail\">\n              <strong>POST /webhook</strong><br>\n              HMAC-SHA256 verified<br>\n              <code>classifyEvent.js</code> (confidence: high)\n            </div>\n          </div>\n\n          <!-- Step 2: Quiet Window -->\n          <div class=\"pipe-step-card\" id=\"pipeStep2\" onclick=\"focusPipelineStep(2)\">\n            <div class=\"pipe-step-icon-halo\">⏳</div>\n            <span class=\"pipe-step-num\">Step 2</span>\n            <h3 class=\"pipe-step-title\">Quiet Window</h3>\n            <p class=\"pipe-step-desc\">The resident gets uninterrupted time to collect the package whenever ready. Picking it up cancels alerts completely.</p>\n            <div class=\"pipe-tech-detail\">\n              <strong>windowService.js</strong><br>\n              Configurable timer (4h / 30s demo)<br>\n              Short visit (15s) = self-resolved\n            </div>\n          </div>\n\n          <!-- Step 3: Night Silence -->\n          <div class=\"pipe-step-card\" id=\"pipeStep3\" onclick=\"focusPipelineStep(3)\">\n            <div class=\"pipe-step-icon-halo\">🌙</div>\n            <span class=\"pipe-step-num\">Step 3</span>\n            <h3 class=\"pipe-step-title\">Night Guard</h3>\n            <p class=\"pipe-step-desc\">Between 10 PM and 7 AM, notifications pause peacefully so remote family members sleep without midnight interruptions.</p>\n            <div class=\"pipe-tech-detail\">\n              <strong>settings.js</strong><br>\n              <code>isInsideQuietHours()</code> check<br>\n              Holds escalation until morning\n            </div>\n          </div>\n\n          <!-- Step 4: AI Caregiver Digest -->\n          <div class=\"pipe-step-card\" id=\"pipeStep4\" onclick=\"focusPipelineStep(4)\">\n            <div class=\"pipe-step-icon-halo\">💌</div>\n            <span class=\"pipe-step-num\">Step 4</span>\n            <h3 class=\"pipe-step-title\">Thoughtful Nudge</h3>\n            <p class=\"pipe-step-desc\">If still outside after the window, Amazon Bedrock writes a warm, empathetic note for the family based on chosen tone.</p>\n            <div class=\"pipe-tech-detail\">\n              <strong>AWS Bedrock (Haiku 4.5)</strong><br>\n              Gentle / Direct / Urgent tone<br>\n              HTTP 429 quota fallback engine\n            </div>\n          </div>\n        </div>\n      </div>\n    </main>\n  </div>\n\n  <!-- Toast Notification Container -->\n  <div class=\"toast-container\" id=\"toastContainer\"></div>\n\n  <!-- Client Scripts -->\n  <script src=\"/js/sound.js\"></script>\n  <script src=\"/js/motion.js\"></script>\n  <script src=\"/js/app.js\"></script>\n</body>\n</html>\n";
